        .modal-actions { display: flex; justify-content: space-between; margin-top: 1.5rem; gap: 0.5rem; flex-wrap: wrap; }

        .toast { position: fixed; bottom: 1.5rem; right: 1.5rem; background: #0f172a; color: #fff; padding: 0.75rem 1.25rem; border-radius: 0.375rem; font-size: 0.875rem; display: none; box-shadow: 0 10px 15px -3px rgba(0,0,0,0.1); z-index: 200; }

