        @media (max-width: 640px) {
            body { padding: 1rem; }
            header { flex-direction: column; align-items: flex-start; gap: 0.75rem; }
            .actions { width: 100%; }
            .actions button { flex: 1 1 auto; justify-content: center; text-align: center; font-size: 0.8rem; padding: 0.5rem 0.75rem; }
