</head>
<body>

    <header>
        <div>
            <h1>Clinic Callback Queue</h1>
        </div>
        <div class="actions">
            <button class="btn-primary" onclick="openModal()">+ Add Request</button>
            <button onclick="copyHandoff()">Copy Handoff</button>
            <button onclick="window.print()">Print Handoff</button>
        </div>
    </header>

    <main class="board">
        <div class="lane lane-new">
            <div class="lane-header">
                <span>Needs Review / New</span>
                <span class="lane-count" id="count-new">0</span>
            </div>
            <div class="queue-list" id="lane-new" ondragover="allowDrop(event)" ondrop="drop(event, 'new')"></div>
        </div>

        <div class="lane lane-pending">
            <div class="lane-header">
                <span>In Progress / Pending</span>
                <span class="lane-count" id="count-pending">0</span>
            </div>
            <div class="queue-list" id="lane-pending" ondragover="allowDrop(event)" ondrop="drop(event, 'pending')"></div>
        </div>

        <div class="lane lane-complete">
            <div class="lane-header">
                <span>Completed</span>
                <span class="lane-count" id="count-complete">0</span>
            </div>
            <div class="queue-list" id="lane-complete" ondragover="allowDrop(event)" ondrop="drop(event, 'complete')"></div>
        </div>
    </main>

    <div class="modal-backdrop" id="modalBackdrop" onclick="closeModal(event)">
        <div class="modal" onclick="event.stopPropagation()">
            <div class="modal-title" id="modalTitle">Add Callback Request</div>
            <form id="requestForm" onsubmit="saveRequest(event)">
                <input type="hidden" id="requestId">
                <div class="form-group">
                    <label for="patientName">Patient Name *</label>
                    <input type="text" id="patientName" required autocomplete="off">
                </div>
                <div class="form-group">
                    <label for="patientPhone">Callback Phone Number *</label>
                    <input type="text" id="patientPhone" required autocomplete="off">
                </div>
                <div class="form-group">
                    <label for="reason">Reason for Call / Request Details *</label>
                    <textarea id="reason" required></textarea>
                </div>
                <div class="form-group">
                    <label for="provider">Assign Provider / Staff</label>
                    <input type="text" id="provider" placeholder="e.g., Dr. Smith, Triage Nurse" autocomplete="off">
                </div>
                <div class="form-group">
                    <label for="status">Status</label>
                    <select id="status">
                        <option value="new">Needs Review / New</option>
                        <option value="pending">In Progress / Pending</option>
                        <option value="complete">Completed</option>
                    </select>
                </div>
                <div class="modal-actions">
                    <button type="button" id="deleteBtn" style="color:var(--danger); border-color:var(--danger);" onclick="deleteRequest()">Delete</button>
                    <div style="display:flex; gap:0.5rem; flex-wrap: wrap;">
                        <button type="button" onclick="closeModal()">Cancel</button>
                        <button type="submit" class="btn-primary">Save Request</button>
                    </div>
                </div>
            </form>
        </div>
    </div>

    <div id="print-section">
        <h2>Clinic Callback Handoff Sheet</h2>
        <p id="print-date" style="margin-bottom: 1rem; font-size: 0.9rem; color: #555;"></p>
        <table class="print-table">
            <thead>
                <tr>
                    <th style="width: 15%;">Patient</th>
                    <th style="width: 15%;">Phone</th>
                    <th style="width: 40%;">Reason/Details</th>
                    <th style="width: 15%;">Assigned</th>
                    <th style="width: 15%;">Status</th>
                </tr>
            </thead>
            <tbody id="print-table-body"></tbody>
        </table>
    </div>

    <div class="toast" id="toast">Handoff copied to clipboard!</div>

    <script>
        let requests = JSON.parse(localStorage.getItem('clinic_callbacks')) || [];

        function renderBoard() {
            const lanes = { new: [], pending: [], complete: [] };
            requests.forEach(req => { if (lanes[req.status]) lanes[req.status].push(req); });

            ['new', 'pending', 'complete'].forEach(status => {
                const container = document.getElementById(`lane-${status}`);
                const countBadge = document.getElementById(`count-${status}`);
                container.innerHTML = '';
                countBadge.textContent = lanes[status].length;

                lanes[status].sort((a, b) => b.timestamp - a.timestamp);

                lanes[status].forEach(req => {
                    const card = document.createElement('div');
                    card.className = 'card';
                    card.draggable = true;
                    card.ondragstart = (e) => drag(e, req.id);
                    card.onclick = () => openModal(req.id);

                    const timeStr = new Date(req.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});

                    card.innerHTML = `
                        <div class="card-header">
                            <span class="patient-name">${escapeHTML(req.name)}</span>
                            <span class="meta-time">${timeStr}</span>
                        </div>
                        <div class="card-body">${escapeHTML(req.reason)}</div>
                        <div class="card-footer">
                            <span>📞 ${escapeHTML(req.phone)}</span>
                            <span style="font-weight:500; color:#475569;">${req.provider ? escapeHTML(req.provider) : 'Unassigned'}</span>
                        </div>
                    `;
                    container.appendChild(card);
                });
            });
            saveToStorage();
            updatePrintView();
        }

        function openModal(id = null) {
            const modal = document.getElementById('modalBackdrop');
            const form = document.getElementById('requestForm');
            const deleteBtn = document.getElementById('deleteBtn');
            form.reset();

            if (id) {
                const req = requests.find(r => r.id === id);
                if (!req) return;
                document.getElementById('modalTitle').textContent = 'Edit Callback Request';
                document.getElementById('requestId').value = req.id;
                document.getElementById('patientName').value = req.name;
                document.getElementById('patientPhone').value = req.phone;
                document.getElementById('reason').value = req.reason;
                document.getElementById('provider').value = req.provider || '';
                document.getElementById('status').value = req.status;
                deleteBtn.style.display = 'block';
            } else {
                document.getElementById('modalTitle').textContent = 'Add Callback Request';
                document.getElementById('requestId').value = '';
                document.getElementById('status').value = 'new';
                deleteBtn.style.display = 'none';
            }
            modal.style.display = 'flex';
            document.getElementById('patientName').focus();
        }

        function closeModal(e = null) {
            document.getElementById('modalBackdrop').style.display = 'none';
        }

        function saveRequest(e) {
            e.preventDefault();
            const id = document.getElementById('requestId').value;
            const name = document.getElementById('patientName').value.trim();
            const phone = document.getElementById('patientPhone').value.trim();
            const reason = document.getElementById('reason').value.trim();
            const provider = document.getElementById('provider').value.trim();
            const status = document.getElementById('status').value;

            if (id) {
                const req = requests.find(r => r.id === id);
                if (req) {
                    req.name = name;
                    req.phone = phone;
                    req.reason = reason;
                    req.provider = provider;
                    req.status = status;
                }
            } else {
                requests.push({
                    id: crypto.randomUUID ? crypto.randomUUID() : '_' + Math.random().toString(36).substr(2, 9),
                    name, phone, reason, provider, status,
                    timestamp: Date.now()
                });
            }
            closeModal();
            renderBoard();
        }

        function deleteRequest() {
            const id = document.getElementById('requestId').value;
            if (id && confirm('Delete this callback request permanently?')) {
                requests = requests.filter(r => r.id !== id);
                closeModal();
                renderBoard();
            }
        }

        function drag(e, id) { e.dataTransfer.setData("text/plain", id); }
        function allowDrop(e) { e.preventDefault(); }
        function drop(e, targetStatus) {
            e.preventDefault();
            const id = e.dataTransfer.getData("text/plain");
            const req = requests.find(r => r.id === id);
            if (req && req.status !== targetStatus) {
                req.status = targetStatus;
                renderBoard();
            }
        }

        function generateHandoffText() {
            if (requests.length === 0) return "No active callback requests.";

            const statusLabels = { new: "🚨 NEW/REVIEW", pending: "⏳ IN PROGRESS", complete: "✅ COMPLETED" };
            let output = `CLINIC CALLBACK HANDOFF SUMMARY - ${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}\n`;
            output += `==================================================\n\n`;

            ['new', 'pending', 'complete'].forEach(status => {
                const list = requests.filter(r => r.status === status);
                if (list.length > 0) {
                    output += `${statusLabels[status]} (${list.length})\n`;
                    output += `--------------------------------------------------\n`;
                    list.forEach(r => {
                        const time = new Date(r.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
                        output += `• Pt: ${r.name} (${r.phone}) [Rec'd: ${time}]\n`;
                        output += `  Details: ${r.reason}\n`;
                        output += `  Assigned: ${r.provider || 'Unassigned'}\n\n`;
                    });
                }
            });
            return output;
        }

        function copyHandoff() {
            const text = generateHandoffText();
            navigator.clipboard.writeText(text).then(() => {
                const toast = document.getElementById('toast');
                toast.style.display = 'block';
                setTimeout(() => toast.style.display = 'none', 2500);
            });
        }

        function updatePrintView() {
            document.getElementById('print-date').textContent = `Generated on: ${new Date().toLocaleString()}`;
            const tbody = document.getElementById('print-table-body');
            tbody.innerHTML = '';

            if (requests.length === 0) {
                tbody.innerHTML = `<tr><td colspan="5" style="text-align:center;">No entries found.</td></tr>`;
                return;
            }

            const sortedForPrint = [...requests].sort((a, b) => {
                const order = { new: 1, pending: 2, complete: 3 };
                return order[a.status] - order[b.status];
            });

            sortedForPrint.forEach(r => {
                const row = document.createElement('tr');
                const statusLabels = { new: "New", pending: "In Progress", complete: "Complete" };
                row.innerHTML = `
                    <td><strong>${escapeHTML(r.name)}</strong></td>
                    <td>${escapeHTML(r.phone)}</td>
                    <td>${escapeHTML(r.reason)}</td>
                    <td>${r.provider ? escapeHTML(r.provider) : '—'}</td>
                    <td>${statusLabels[r.status]}</td>
                `;
                tbody.appendChild(row);
            });
        }

        function saveToStorage() { localStorage.setItem('clinic_callbacks', JSON.stringify(requests)); }
        function escapeHTML(str) { return str.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;"); }

        renderBoard();
    </script>
</body>
</html>

